<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { useRouter } from 'vue-router'; import AppLayout from '@/layouts/AppLayout.vue'; import KnowledgeCard from '@/components/KnowledgeCard.vue'; import * as api from '@/api/knowledge'; import type { KnowledgeBase } from '@/types'
const router = useRouter(); const items = ref<KnowledgeBase[]>([]); const keyword = ref(''); const dialog = ref(false); const editing = ref<KnowledgeBase | null>(null); const form = ref({ name: '', description: '' })
async function load() { try { items.value = await api.listKnowledgeBases(keyword.value) } catch { items.value = [] } }
function openCreate() { editing.value = null; form.value = { name: '', description: '' }; dialog.value = true }
function openEdit(item: KnowledgeBase) { editing.value = item; form.value = { name: item.name, description: item.description || '' }; dialog.value = true }
async function save() { try { editing.value ? await api.updateKnowledgeBase(editing.value.id, form.value) : await api.createKnowledgeBase(form.value); dialog.value = false; ElMessage.success(editing.value ? '知识库已更新' : '知识库已创建'); load() } catch (error: any) { ElMessage.error(error.response?.data?.message || '保存失败') } }
async function remove(item: KnowledgeBase) { await ElMessageBox.confirm(`确定删除“${item.name}”吗？其中的文档和索引也会被清理。`, '删除知识库', { type: 'warning' }); try { await api.deleteKnowledgeBase(item.id); ElMessage.success('知识库已删除'); load() } catch { ElMessage.error('删除失败') } }
onMounted(load)
</script>
<template><AppLayout><div class="page-heading"><div><p class="eyebrow">KNOWLEDGE BASES</p><h1>我的知识库</h1><p>按主题组织资料，让检索范围清晰可控。</p></div><button class="primary-button compact" @click="openCreate">＋ 新建知识库</button></div><div class="toolbar"><div class="search-box">⌕<input v-model="keyword" placeholder="搜索知识库" @keyup.enter="load"/><button @click="load">搜索</button></div><span class="result-count">共 {{ items.length }} 个知识库</span></div><div v-if="items.length" class="knowledge-grid"><KnowledgeCard v-for="item in items" :key="item.id" :item="item" @open="id => router.push(`/knowledge/${id}`)" @edit="openEdit" @remove="remove"/></div><div v-else class="empty-state"><div>▣</div><h2>还没有知识库</h2><p>创建第一个知识库，开始上传学习资料。</p><button class="primary-button" @click="openCreate">创建知识库</button></div><el-dialog v-model="dialog" :title="editing ? '编辑知识库' : '新建知识库'" width="460px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name" maxlength="100" show-word-limit /></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="500" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></AppLayout></template>

